<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;use Laravel\Sanctum\HasApiTokens;
class User extends Authenticatable{use HasApiTokens,HasFactory,Notifiable;protected $fillable=['name','email','password','graduating_year','phone','occupation','company','bio','location','photo_url','role','status','privacy','approved_by','approved_at'];protected $hidden=['password','remember_token'];protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed','privacy'=>'array','approved_at'=>'datetime'];}public function set(){return $this->belongsTo(AlumniSet::class,'graduating_year','year');}public function administeredSets(){return $this->belongsToMany(AlumniSet::class,'alumni_set_admins')->withPivot(['is_primary','active','assigned_by'])->withTimestamps()->wherePivot('active',true);}public function approvals(){return $this->hasMany(self::class,'approved_by');}public function activities(){return $this->hasMany(MemberActivity::class)->latest('occurred_at');}}
